import{_ as l,a0 as o,w as h,s as d,ao as p,I as t,a1 as e,A as n,x as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"如何在 Linux 上查找硬件规格 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 上查找硬件规格 | LCTT (201908) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 上查找硬件规格 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 上查找硬件规格 | LCTT (201908) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201908/20190805 How To Find Hardware Specifications On Linux","title":"如何在 Linux 上查找硬件规格","tag":"201908","desc":""},"relativePath":"201908/20190805 How To Find Hardware Specifications On Linux.md","filePath":"[post].md"}'),r={name:"201908/20190805 How To Find Hardware Specifications On Linux.md"};function c(g,s,u,k,b,f){const a=o("Link");return h(),d("div",null,[s[19]||(s[19]=p(`<h1 id="如何在-linux-上查找硬件规格" tabindex="-1">如何在 Linux 上查找硬件规格 <a class="header-anchor" href="#如何在-linux-上查找硬件规格" aria-label="Permalink to “如何在 Linux 上查找硬件规格”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/201908/06/111717t1f77n7v3egxhf18.jpg" alt=""></p><p>在 Linux 系统上有许多工具可用于查找硬件规格。在这里，我列出了四种最常用的工具，可以获取 Linux 系统的几乎所有硬件（和软件）细节。好在是这些工具在某些 Linux 发行版上默认预装。我在 Ubuntu 18.04 LTS 桌面上测试了这些工具，但是它们也适用于其他 Linux 发行版。</p><h3 id="_1、lshw" tabindex="-1">1、LSHW <a class="header-anchor" href="#_1、lshw" aria-label="Permalink to “1、LSHW”">​</a></h3><p>lshw（硬件列表）是一个简单但功能齐全的实用程序，它提供了 Linux 系统上的硬件规格的详细信息。它可以报告确切的内存规格、固件版本、主板规格、CPU 版本和速度、缓存规格、总线速度等。信息可以以纯文本、XML 或 HTML 格式输出。</p><p>它目前支持 DMI（仅限 x86 和 EFI）、Open Firmware 设备树（仅限 PowerPC）、PCI/AGP、ISA PnP（x86）、CPUID（x86）、IDE/ATA/ATAPI、PCMCIA（仅在 x86 上测试过）、USB 和 SCSI。</p><p>就像我已经说过的那样，Ubuntu 默认预装了 lshw。如果它未安装在你的 Ubuntu 系统中，请使用以下命令安装它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install lshw lshw-gtk</span></span></code></pre></div><p>在其他 Linux 发行版上，例如 Arch Linux，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pacman -S lshw lshw-gtk</span></span></code></pre></div><p>安装后，运行 <code>lshw</code> 以查找系统硬件详细信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lshw</span></span></code></pre></div><p>你将看到输出详细的系统硬件。</p><p>示例输出：</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2013/01/Find-Hardware-Specifications-On-Linux-using-lshw-1.png" alt=""></p><p><em>使用 lshw 在 Linux 上查找硬件规格</em></p><p>请注意，如果你没有以 <code>sudo</code> 权限运行 <code>lshw</code> 命令，则输出可能不完整或不准确。</p><p><code>lshw</code> 可以将输出显示为 HTML 页面。为此，请使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lshw -html</span></span></code></pre></div><p>同样，我们可以将设备树输出为 XML 和 json 格式，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lshw -xml</span></span>
<span class="line"><span>$ sudo lshw -json</span></span></code></pre></div><p>要输出显示硬件路径的设备树，请使用 <code>-short</code> 选项：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lshw -short</span></span></code></pre></div><p><img src="https://www.ostechnix.com/wp-content/uploads/2013/01/Show-device-tree-with-hardware-path-using-lshw.png" alt=""></p><p><em>使用 lshw 显示具有硬件路径的设备树</em></p><p>要列出设备的总线信息、详细的 SCSI、USB、IDE 和 PCI 地址，请运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lshw -businfo</span></span></code></pre></div><p>默认情况下，<code>lshw</code> 显示所有硬件详细信息。你还可以使用类选项查看特定硬件详细信息的硬件信息，例如处理器、内存、显示器等。可以使用 <code>lshw -short</code> 或 <code>lshw -businfo</code> 找到类选项。</p><p>要显示特定硬件详细信息，例如处理器，请执行以下操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lshw -class processor</span></span></code></pre></div><p>示例输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>*-cpu</span></span>
<span class="line"><span>description: CPU</span></span>
<span class="line"><span>product: Intel(R) Core(TM) i3-2350M CPU @ 2.30GHz</span></span>
<span class="line"><span>vendor: Intel Corp.</span></span>
<span class="line"><span>physical id: 4</span></span>
<span class="line"><span>bus info: [email protected]</span></span>
<span class="line"><span>version: Intel(R) Core(TM) i3-2350M CPU @ 2.30GHz</span></span>
<span class="line"><span>serial: To Be Filled By O.E.M.</span></span>
<span class="line"><span>slot: CPU 1</span></span>
<span class="line"><span>size: 913MHz</span></span>
<span class="line"><span>capacity: 2300MHz</span></span>
<span class="line"><span>width: 64 bits</span></span>
<span class="line"><span>clock: 100MHz</span></span>
<span class="line"><span>capabilities: x86-64 fpu fpu_exception wp vme de pse tsc msr pae mce cx8 apic sep mtrr pge mca cmov pat pse36 clflush dts acpi mmx fxsr sse sse2 ss ht tm pbe syscall nx rdtscp constant_tsc arch_perfmon pebs bts rep_good nopl xtopology nonstop_tsc cpuid aperfmperf pni pclmulqdq dtes64 monitor ds_cpl vmx est tm2 ssse3 cx16 xtpr pdcm pcid sse4_1 sse4_2 x2apic popcnt tsc_deadline_timer xsave avx lahf_lm epb pti ssbd ibrs ibpb stibp tpr_shadow vnmi flexpriority ept vpid xsaveopt dtherm arat pln pts md_clear flush_l1d cpufreq</span></span>
<span class="line"><span>configuration: cores=2 enabledcores=1 threads=2</span></span></code></pre></div><p>类似的，你可以得到系统细节：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lshw -class system</span></span></code></pre></div><p>硬盘细节：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lshw -class disk</span></span></code></pre></div><p>网络细节：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lshw -class network</span></span></code></pre></div><p>内存细节：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lshw -class memory</span></span></code></pre></div><p>你也可以像下面这样列出多个设备的细节：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lshw -class storage -class power -class volume</span></span></code></pre></div><p>如果你想要查看带有硬件路径的细节信息，加上 <code>-short</code> 选项即可：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lshw -short -class processor</span></span></code></pre></div><p>示例输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>H/W path Device Class Description</span></span>
<span class="line"><span>=======================================================</span></span>
<span class="line"><span>/0/4 processor Intel(R) Core(TM) i3-2350M CPU @ 2.30GHz</span></span></code></pre></div><p>有时，你可能希望将某些硬件详细信息共享给别人，例如客户支持人员。如果是这样，你可以从输出中删除潜在的敏感信息，如 IP 地址、序列号等，如下所示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lshw -sanitize</span></span></code></pre></div><h4 id="lshw-gtk-gui-工具" tabindex="-1">lshw-gtk GUI 工具 <a class="header-anchor" href="#lshw-gtk-gui-工具" aria-label="Permalink to “lshw-gtk GUI 工具”">​</a></h4><p>如果你对 CLI 不熟悉，可以使用 <code>lshw-gtk</code>，这是 <code>lshw</code> 命令行工具的图形界面。</p><p>它可以从终端或 Dash 中打开。</p><p>要从终端启动它，只需执行以下操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lshw-gtk</span></span></code></pre></div><p>这是 <code>lshw</code> 工具的默认 GUI 界面。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2013/01/Find-Hardware-Specifications-On-Linux-using-lshw-gtk-1.png" alt=""></p><p><em>使用 lshw-gtk 在 Linux 上查找硬件</em></p><p>只需双击“Portable Computer”即可进一步展开细节。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2013/01/Find-Hardware-Specifications-On-Linux-using-lshw-gtk-2.png" alt=""></p><p><em>使用 lshw-gtk GUI 在 Linux 上查找硬件</em></p><p>你可以双击后续的硬件选项卡以获取详细视图。</p><p>有关更多详细信息，请参阅手册页。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man lshw</span></span></code></pre></div><h3 id="_2、inxi" tabindex="-1">2、Inxi <a class="header-anchor" href="#_2、inxi" aria-label="Permalink to “2、Inxi”">​</a></h3><p>Inxi 是我查找 Linux 系统上几乎所有内容的另一个最喜欢的工具。它是一个自由开源的、功能齐全的命令行系统信息工具。它显示了系统硬件、CPU、驱动程序、Xorg、桌面、内核、GCC 版本、进程、RAM 使用情况以及各种其他有用信息。无论是硬盘还是 CPU、主板还是整个系统的完整细节，inxi 都能在几秒钟内更准确地显示它。由于它是 CLI 工具，你可以在桌面或服务器版本中使用它。有关更多详细信息，请参阅以下指南。</p>`,64)),t("ul",null,[t("li",null,[e(a,{href:"https://www.ostechnix.com/how-to-find-your-system-details-using-inxi/"},{default:n(()=>[...s[0]||(s[0]=[i("如何使用 inxi 发现系统细节",-1)])]),_:1})])]),s[20]||(s[20]=p('<h3 id="_3、hardinfo" tabindex="-1">3、Hardinfo <a class="header-anchor" href="#_3、hardinfo" aria-label="Permalink to “3、Hardinfo”">​</a></h3><p>Hardinfo 将为你提供 <code>lshw</code> 中没有的系统硬件和软件详细信息。</p><p>HardInfo 可以收集有关系统硬件和操作系统的信息，执行基准测试，并以 HTML 或纯文本格式生成可打印的报告。</p><p>如果 Ubuntu 中未安装 Hardinfo，请使用以下命令安装：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install hardinfo</span></span></code></pre></div><p>安装后，Hardinfo 工具可以从终端或菜单中进行。</p><p>以下是 Hardinfo 默认界面的外观。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2013/01/Find-Hardware-Specifications-On-Linux-Using-Hardinfo.png" alt=""></p><p><em>使用 Hardinfo 在 Linux 上查找硬件</em></p><p>正如你在上面的屏幕截图中看到的，Hardinfo 的 GUI 简单直观。</p><p>所有硬件信息分为四个主要组：计算机、设备、网络和基准。每个组都显示特定的硬件详细信息。</p><p>例如，要查看处理器详细信息，请单击“设备”组下的“处理器”选项。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2013/01/Show-processor-details-using-hardinfo.png" alt=""></p><p><em>使用 hardinfo 显示处理器详细信息</em></p><p>与 <code>lshw</code> 不同，Hardinfo 可帮助你查找基本软件规范，如操作系统详细信息、内核模块、区域设置信息、文件系统使用情况、用户/组和开发工具等。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2013/01/Show-operating-system-details-using-hardinfo.png" alt=""></p><p><em>使用 hardinfo 显示操作系统详细信息</em></p><p>Hardinfo 的另一个显着特点是它允许我们做简单的基准测试来测试 CPU 和 FPU 功能以及一些图形用户界面功能。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2013/01/Perform-benchmarks-using-hardinfo.png" alt=""></p><p><em>使用 hardinfo 执行基准测试</em></p><p>建议阅读：</p>',21)),t("ul",null,[t("li",null,[e(a,{href:"https://www.ostechnix.com/phoronix-test-suite-open-source-testing-benchmarking-tool/"},{default:n(()=>[...s[1]||(s[1]=[i("Phoronix 测试套件 - 开源测试和基准测试工具",-1)])]),_:1})]),t("li",null,[e(a,{href:"https://www.ostechnix.com/unixbench-benchmark-suite-unix-like-systems/"},{default:n(()=>[...s[2]||(s[2]=[i("UnixBench - 类 Unix 系统的基准套件",-1)])]),_:1})]),t("li",null,[e(a,{href:"https://www.ostechnix.com/how-to-benchmark-linux-commands-and-programs-from-commandline/"},{default:n(()=>[...s[3]||(s[3]=[i("如何从命令行对 Linux 命令和程序进行基准测试",-1)])]),_:1})])]),s[21]||(s[21]=p('<p>我们可以生成整个系统以及各个设备的报告。要生成报告，只需单击菜单栏上的“生成报告”按钮，然后选择要包含在报告中的信息。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2013/01/Generate-system-reports-using-hardinfo.png" alt=""></p><p><em>使用 hardinfo 生成系统报告</em></p><p>Hardinfo 也有几个命令行选项。</p><p>例如，要生成报告并在终端中显示它，请运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ hardinfo -r</span></span></code></pre></div><p>列出模块：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ hardinfo -l</span></span></code></pre></div><p>更多信息请参考手册：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man hardinfo</span></span></code></pre></div><h3 id="_4、sysinfo" tabindex="-1">4、Sysinfo <a class="header-anchor" href="#_4、sysinfo" aria-label="Permalink to “4、Sysinfo”">​</a></h3><p>Sysinfo 是 HardInfo 和 lshw-gtk 实用程序的另一个替代品，可用于获取下面列出的硬件和软件信息。</p><ul><li>系统详细信息，如发行版版本、GNOME 版本、内核、gcc 和 Xorg 以及主机名。</li><li>CPU 详细信息，如供应商标识、型号名称、频率、L2 缓存、型号和标志。</li><li>内存详细信息，如系统全部内存、可用内存、交换空间总量和空闲、缓存、活动/非活动的内存。</li><li>存储控制器，如 IDE 接口、所有 IDE 设备、SCSI 设备。</li><li>硬件详细信息，如主板、图形卡、声卡和网络设备。</li></ul><p>让我们使用以下命令安装 sysinfo：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install sysinfo</span></span></code></pre></div><p>Sysinfo 可以从终端或 Dash 启动。</p><p>要从终端启动它，请运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sysinfo</span></span></code></pre></div><p>这是 Sysinfo 实用程序的默认界面。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2013/01/sysinfo-interface.png" alt=""></p><p><em>sysinfo 界面</em></p><p>如你所见，所有硬件（和软件）详细信息都分为五类，即系统、CPU、内存、存储和硬件。单击导航栏上的类别以获取相应的详细信息。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2013/01/Find-Hardware-Specifications-On-Linux-Using-Sysinfo.png" alt=""></p><p><em>使用 Sysinfo 在 Linux 上查找硬件</em></p><p>更多细节可以在手册页上找到。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man sysinfo</span></span></code></pre></div><p>就这样。就像我已经提到的那样，可以有很多工具可用于显示硬件/软件规范。但是，这四个工具足以找到你的 Linux 发行版的所有软硬件规格信息。</p><hr>',28)),t("p",null,[s[5]||(s[5]=i("via: ",-1)),e(a,{href:"https://www.ostechnix.com/getting-hardwaresoftware-specifications-in-linux-mint-ubuntu/"},{default:n(()=>[...s[4]||(s[4]=[i("https://www.ostechnix.com/getting-hardwaresoftware-specifications-in-linux-mint-ubuntu/",-1)])]),_:1})]),t("p",null,[s[10]||(s[10]=i("作者：",-1)),e(a,{href:"https://www.ostechnix.com/author/sk/"},{default:n(()=>[...s[6]||(s[6]=[i("sk",-1)])]),_:1}),s[11]||(s[11]=i(" 选题：",-1)),e(a,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[7]||(s[7]=[i("lujun9972",-1)])]),_:1}),s[12]||(s[12]=i(" 译者：",-1)),e(a,{href:"https://github.com/wxy"},{default:n(()=>[...s[8]||(s[8]=[i("wxy",-1)])]),_:1}),s[13]||(s[13]=i(" 校对：",-1)),e(a,{href:"https://github.com/wxy"},{default:n(()=>[...s[9]||(s[9]=[i("wxy",-1)])]),_:1})]),t("p",null,[s[16]||(s[16]=i("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[14]||(s[14]=[i("LCTT",-1)])]),_:1}),s[17]||(s[17]=i(" 原创编译，",-1)),e(a,{href:"https://linux.cn/"},{default:n(()=>[...s[15]||(s[15]=[i("Linux中国",-1)])]),_:1}),s[18]||(s[18]=i(" 荣誉推出",-1))])])}const y=l(r,[["render",c]]);export{x as __pageData,y as default};
